import { verifyAdmin } from '../lib/auth';
import { notFound, redirect } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!session) {
    redirect('/login');
  }

  if (!isAdmin) {
    return (
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        fontFamily: 'system-ui, sans-serif',
        padding: '2rem',
        textAlign: 'center'
      }}>
        <h1 style={{ fontSize: '6rem', margin: 0, color: '#dc2626' }}>403</h1>
        <h2 style={{ marginTop: '1rem', fontSize: '1.5rem' }}>Access Denied</h2>
        <p style={{ color: '#6b7280', marginTop: '0.5rem' }}>
          You don&apos;t have permission to access this page.
        </p>
        <p style={{ color: '#9ca3af', marginTop: '0.25rem', fontSize: '0.875rem' }}>
          Required role: <strong>admin</strong>
        </p>
        <p style={{ color: '#9ca3af', marginTop: '1.5rem', fontSize: '0.875rem' }}>
          Current user: <strong>{session.name}</strong> ({session.role})
        </p>
      </div>
    );
  }

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}!</p>
      <p>You have admin access.</p>
    </div>
  );
}

'use client';

import { useEffect } from 'react';
import Link from 'next/link';

export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error('Admin page error:', error);
  }, [error]);

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      fontFamily: 'system-ui, sans-serif',
      padding: '2rem',
      textAlign: 'center'
    }}>
      <h1 style={{ fontSize: '6rem', margin: 0, color: '#dc2626' }}>403</h1>
      <h2 style={{ marginTop: '1rem', fontSize: '1.5rem' }}>Access Denied</h2>
      <p style={{ color: '#6b7280', marginTop: '0.5rem' }}>
        You don&apos;t have permission to access this page.
      </p>
      <div style={{ marginTop: '1.5rem', display: 'flex', gap: '1rem' }}>
        <button
          onClick={() => reset()}
          style={{
            padding: '0.75rem 1.5rem',
            backgroundColor: '#3b82f6',
            color: 'white',
            border: 'none',
            borderRadius: '0.375rem',
            cursor: 'pointer',
            fontSize: '0.875rem'
          }}
        >
          Try Again
        </button>
        <Link
          href="/"
          style={{
            padding: '0.75rem 1.5rem',
            backgroundColor: '#6b7280',
            color: 'white',
            borderRadius: '0.375rem',
            textDecoration: 'none',
            fontSize: '0.875rem'
          }}
        >
          Go Home
        </Link>
      </div>
    </div>
  );
}
